10: <link href="https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;600&family=Pixelify+Sans:wght@500;700&family=Space+Grotesk:wght@400;500;700&display=swap" rel="stylesheet">
11: <style>
12: /* Layout concept: a pixel city that wakes up window by window as an idea moves through the pipeline.
13:    Paper-white ground, one red highlighter, pastel skyline, a corkboard, file tabs, a stamp. */
14: :root{
15:   --paper:#F6F1E7; --paper2:#FFFDF8; --paper3:#EDE3CF;
16:   --ink:#0F1226; --ink2:#454963;
17:   --red:#E5322D; --red-d:#CF2A25;
18:   --green:#2FB36B; --green-d:#1B8548;
19:   --amber:#F2B63D; --teal:#2E8F8B; --coral:#EF6F5E; --plum:#5E3A63; --sky:#4DA3FF;
20:   --mat:#14383A; --night:#161A3D;
21:   --font-d:'Pixelify Sans','Courier New',monospace;
22:   --font-b:'Space Grotesk',system-ui,sans-serif;
23:   --font-m:'JetBrains Mono',ui-monospace,monospace;
24:   --shadow:4px 4px 0 var(--ink);
25:   --r:4px;
26: }
27: *{box-sizing:border-box}
28: html{scroll-behavior:smooth}
29: body{margin:0;background:var(--paper);color:var(--ink);font:400 17px/1.5 var(--font-b);overflow-x:hidden;-webkit-font-smoothing:antialiased}
30: body::before{content:"";position:fixed;inset:0;pointer-events:none;z-index:90;opacity:.3;mix-blend-mode:multiply;
31:   background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='220' height='220'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='2' stitchTiles='stitch'/><feColorMatrix values='0 0 0 0 .06  0 0 0 0 .07  0 0 0 0 .15  0 0 0 .5 0'/></filter><rect width='100%' height='100%' filter='url(%23n)'/></svg>")}
32: h1,h2,h3,p,figure{margin:0}
33: button{font:inherit;color:inherit}
34: a{color:inherit}
35: :focus-visible{outline:3px solid var(--plum);outline-offset:3px}
36: .dark :focus-visible,.night :focus-visible,.mat :focus-visible{outline-color:var(--amber)}
37: .sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
38: .skip{position:absolute;left:12px;top:-60px;z-index:200;background:var(--ink);color:var(--paper);padding:10px 14px;border-radius:var(--r)}
39: .skip:focus{top:12px}
40: .wrap{width:min(1240px,100% - 32px);margin-inline:auto}
41: canvas{image-rendering:pixelated;image-rendering:crisp-edges}
42: .eyebrow{font:600 12px/1 var(--font-m);letter-spacing:.16em;text-transform:uppercase;display:flex;align-items:center;gap:10px}
43: .eyebrow .dash{width:28px;height:2px;background:var(--red-d)}
44: .h2{font:700 clamp(30px,4.4vw,54px)/1.05 var(--font-d);text-transform:uppercase;letter-spacing:.01em;text-wrap:balance}
45: .h2 em{font-style:normal;color:var(--red)}
46: .lead{font-size:clamp(17px,1.5vw,20px);max-width:60ch;color:var(--ink2)}
47: .btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;font:700 16px/1 var(--font-b);padding:14px 20px;border:2px solid var(--ink);border-radius:var(--r);background:var(--paper2);box-shadow:var(--shadow);cursor:pointer;text-decoration:none;transition:transform .08s ease-out,box-shadow .08s ease-out}
48: .btn:hover{transform:translate(-1px,-1px);box-shadow:5px 5px 0 var(--ink)}
49: .btn:active{transform:translate(4px,4px);box-shadow:0 0 0 var(--ink)}
50: .btn-red{background:var(--red-d);color:#fff}
51: .btn-ink{background:var(--ink);color:var(--paper);border-color:var(--ink);box-shadow:4px 4px 0 var(--red)}
52: .btn-sm{padding:9px 14px;font-size:14px}
53: .btn[disabled],.btn[aria-disabled="true"]{opacity:.5;cursor:not-allowed;box-shadow:none;transform:none}
54: .chip{display:inline-flex;align-items:center;gap:6px;font:600 11px/1 var(--font-m);letter-spacing:.1em;text-transform:uppercase;padding:5px 8px;border:2px solid var(--ink);border-radius:var(--r);background:var(--paper2)}
55: .chip.found{background:var(--green-d);color:#fff;border-color:var(--ink)}
56: .chip.pend{background:var(--amber);color:var(--ink)}
57: .chip.sim{background:var(--plum);color:#fff}
58: .chip.ill{background:var(--sky);color:var(--ink)}
59: .chip.ass{background:var(--paper3)}
60: .chip.meas{background:var(--teal);color:#fff}
61: .chip.comp{background:#B79AD0;color:var(--ink)}
62: .abt{width:100%;border-collapse:collapse;font:500 13px/1.3 var(--font-m);margin:6px 0 4px}
63: .abt th,.abt td{text-align:left;padding:7px 8px;border:2px solid var(--ink);background:#fff}
64: .abt th{font:600 11px/1 var(--font-m);letter-spacing:.1em;text-transform:uppercase;color:var(--ink2);background:var(--paper3)}
65: .abt td b{font-weight:700}
66: .abh{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:14px 0 4px}
67: .abh h5{margin:0;font:600 12px/1.2 var(--font-m);letter-spacing:.08em;text-transform:uppercase}
68: .limit{margin-top:12px;padding:12px 14px;border:2px dashed var(--ink);border-radius:var(--r);background:rgba(255,255,255,.6);font:500 13px/1.45 var(--font-b)}
69: .mgrid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-top:6px}
70: .mcell{border:2px solid var(--ink);border-radius:var(--r);padding:14px;background:#fff;min-width:0}
71: .mcell h4{margin:0 0 8px;font:600 11px/1.2 var(--font-m);letter-spacing:.1em;text-transform:uppercase;color:var(--ink2);display:flex;gap:8px;align-items:center;flex-wrap:wrap}
72: .mcell .vv{font:700 20px/1.25 var(--font-m);word-break:break-word}
73: .mcell .vv small{display:block;font:500 11px/1.3 var(--font-m);color:var(--ink2);text-transform:uppercase;letter-spacing:.08em}
74: .mcell .dl{margin-top:8px;font:700 14px/1 var(--font-m);color:var(--green-d)}
75: @media (max-width:760px){.mgrid{grid-template-columns:minmax(0,1fr)}}
76: .copy{font:600 11px/1 var(--font-m);letter-spacing:.06em;border:2px solid var(--ink);background:var(--paper2);border-radius:var(--r);padding:5px 8px;cursor:pointer;box-shadow:2px 2px 0 var(--ink);white-space:nowrap}
77: .copy:active{transform:translate(2px,2px);box-shadow:none}
78: code,.mono{font-family:var(--font-m)}
79: 
80: /* NAV */
81: .nav{position:sticky;top:env(safe-area-inset-top,0px);z-index:80;background:rgba(246,241,231,.92);backdrop-filter:blur(6px);border-bottom:2px solid var(--ink)}
82: .navin{display:flex;align-items:center;gap:20px;padding-block:10px}
83: .mark{display:flex;align-items:center;gap:8px;text-decoration:none;font:700 20px/1 var(--font-d);letter-spacing:.02em;white-space:nowrap}
84: .mark canvas{display:block;image-rendering:pixelated}
85: .navin nav{display:flex;gap:18px;margin-left:8px}
86: .navin nav a{font:600 14px/1 var(--font-b);text-decoration:none;padding:6px 2px;border-bottom:2px solid transparent}
87: .navin nav a:hover{border-color:var(--red-d)}
88: .tag{margin-left:auto;font:500 12px/1 var(--font-m);color:var(--ink2);overflow:hidden;height:14px;min-width:0}
89: .tag span{display:block;animation:tagin .35s ease-out}
90: @keyframes tagin{from{transform:translateY(100%)}to{transform:none}}
91: 
92: /* HERO */
93: .hero{position:relative;padding-top:clamp(28px,4vw,56px);padding-bottom:clamp(16px,3vw,32px)}
94: .glow{position:absolute;right:-10%;top:-10%;width:70%;height:90%;background:radial-gradient(closest-side,rgba(77,163,255,.28),rgba(242,182,61,.14) 55%,transparent 75%);pointer-events:none}
95: .herogrid{position:relative;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.12fr);gap:clamp(24px,4vw,56px);align-items:center}
96: .herotext{display:flex;flex-direction:column;gap:22px;min-width:0}
97: h1{font:700 clamp(46px,6.4vw,96px)/.9 var(--font-d);text-transform:uppercase;letter-spacing:-.015em}
98: h1 em{font-style:normal;color:var(--red)}
99: .sub{font-size:clamp(17px,1.5vw,20px);max-width:52ch;color:var(--ink2)}
100: .ideaform{display:flex;gap:10px;flex-wrap:wrap}
101: .ideaform input{flex:1 1 220px;min-width:0;font:500 16px var(--font-b);padding:14px 14px;border:2px solid var(--ink);border-radius:var(--r);background:var(--paper2);box-shadow:inset 3px 3px 0 rgba(15,18,38,.08)}
102: .ideaform input::placeholder{color:#6A6E86}
103: .chiprow{display:flex;gap:8px;flex-wrap:wrap}
104: .ichip{font:500 13px/1.2 var(--font-b);padding:7px 11px;border:2px solid var(--ink);border-radius:999px;background:var(--paper2);cursor:pointer;transition:transform .08s}
105: .ichip:nth-child(1){background:#FBD9D2;transform:rotate(-1.5deg)}
106: .ichip:nth-child(2){background:#D4ECE6;transform:rotate(1deg)}
107: .ichip:nth-child(3){background:#FCEBC2;transform:rotate(-.5deg)}
108: .ichip:hover{transform:translateY(-2px) rotate(0)}
109: .btnrow{display:flex;gap:12px;flex-wrap:wrap}
110: .frame{background:var(--ink);border:2px solid var(--ink);border-radius:6px;box-shadow:8px 8px 0 var(--red);padding:10px;color:var(--paper);min-width:0}
111: .frame-bar{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:0 2px 8px}
112: .dots{display:flex;gap:6px}.dots i{width:10px;height:10px;border-radius:50%;background:var(--coral)}.dots i:nth-child(2){background:var(--amber)}.dots i:nth-child(3){background:var(--green)}
113: #office{display:block;width:100%;height:auto;aspect-ratio:16/9;background:#F3EAD7;border:2px solid #2B3358;cursor:crosshair}
114: .cap{font:500 14px/1.3 var(--font-m);padding:10px 2px 4px;min-height:2.4em;color:var(--paper)}
115: .ctrl{display:flex;gap:8px;flex-wrap:wrap;align-items:center;padding-top:6px}
116: .cbtn{font:600 12px/1 var(--font-m);padding:8px 10px;border:2px solid var(--paper);background:transparent;color:var(--paper);border-radius:var(--r);cursor:pointer}
117: .cbtn[aria-pressed="true"]{background:var(--amber);color:var(--ink);border-color:var(--amber)}
118: .cbtn:hover{background:var(--paper);color:var(--ink)}
119: .ctrl .note{margin-left:auto;font:400 12px/1.3 var(--font-m);color:#C9CCE0}
120: .ctrl .note a{color:var(--amber)}
121: .skywrap{position:relative;height:150px;margin-top:8px}
122: #heroSky{position:absolute;inset:0;width:100%;height:100%}
123: .ground{background:var(--ink);color:var(--paper);border-top:4px solid var(--ink)}
124: .statrow{display:grid;grid-template-columns:repeat(3,1fr) auto;gap:12px 28px;align-items:center;padding-block:22px}
125: .stat{display:flex;align-items:baseline;gap:10px;flex-wrap:wrap}
126: .stat b{font:700 clamp(34px,4.4vw,56px)/1 var(--font-d);color:var(--paper);font-variant-numeric:tabular-nums}
127: .stat span{font:600 13px/1.2 var(--font-m);letter-spacing:.06em;text-transform:uppercase;color:#D6D9EA}
128: .statrow .real{font:500 12px/1.4 var(--font-m);color:#C9CCE0;max-width:26ch}
129: 
130: /* GAP */
131: .gap{position:relative;overflow:hidden;background:linear-gradient(#F6F1E7 0%,#FADFCB 55%,#F4C6B6 100%);padding-block:clamp(56px,8vw,110px) clamp(160px,18vw,260px)}
132: .gap .sky{position:absolute;left:-6%;width:112%;bottom:0;height:200px;will-change:transform}
133: .gap .sky.far{opacity:.45;bottom:40px;height:170px}
134: .gap-in{position:relative;z-index:2;display:flex;flex-direction:column;gap:26px}
135: .big{font:500 clamp(26px,3.8vw,48px)/1.2 var(--font-d);letter-spacing:.02em;text-transform:uppercase;max-width:26ch;min-height:3.6em}
136: .big .cur{display:inline-block;width:.5em;height:.9em;background:var(--red);vertical-align:-.1em;animation:blink 1s steps(2) infinite}
137: @keyframes blink{50%{opacity:0}}
138: .chips3{display:flex;gap:10px;flex-wrap:wrap}
139: .chips3 span{font:700 14px/1 var(--font-m);padding:10px 12px;border:2px solid var(--ink);border-radius:var(--r);background:var(--paper2);box-shadow:3px 3px 0 var(--ink)}
140: .chips3 .hot{background:var(--red-d);color:#fff}
141: .mood{display:flex;flex-wrap:wrap;gap:14px;margin-top:6px}
142: .tile{font:500 15px/1.25 var(--font-b);padding:14px 16px 12px;border:2px solid var(--ink);border-radius:var(--r);box-shadow:var(--shadow);max-width:230px;position:relative}
143: .tile::after{content:"";position:absolute;right:8px;top:8px;width:8px;height:8px;background:var(--ink);clip-path:polygon(50% 0,62% 38%,100% 50%,62% 62%,50% 100%,38% 62%,0 50%,38% 38%)}
144: .tile small{display:block;margin-top:8px;font:600 10px/1 var(--font-m);letter-spacing:.12em;text-transform:uppercase;opacity:.75}
145: .float{position:absolute;z-index:1;width:14px;height:14px;background:var(--sky);box-shadow:3px 3px 0 var(--ink);border:2px solid var(--ink)}
146: 
147: /* ORBIT BAND */
148: .night{position:relative;overflow:hidden;color:var(--paper);background:radial-gradient(ellipse at 50% 120%,#3B2D6B 0%,#1A1E4A 45%,#0F1226 100%);padding-block:clamp(48px,7vw,90px)}
149: .night::before{content:"";position:absolute;inset:0;opacity:.8;background-image:radial-gradient(1.5px 1.5px at 12% 22%,#fff,transparent),radial-gradient(1px 1px at 28% 70%,#fff,transparent),radial-gradient(1.5px 1.5px at 44% 18%,#F2B63D,transparent),radial-gradient(1px 1px at 63% 62%,#fff,transparent),radial-gradient(1.5px 1.5px at 78% 28%,#fff,transparent),radial-gradient(1px 1px at 90% 74%,#4DA3FF,transparent),radial-gradient(1px 1px at 6% 82%,#fff,transparent),radial-gradient(1.5px 1.5px at 54% 88%,#fff,transparent)}
150: .night-in{position:relative;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:32px;align-items:center}
151: .night .lead{color:#D6D9EA}
152: .orbit{position:relative;width:min(440px,100%);aspect-ratio:1;margin-inline:auto}
153: .ring{position:absolute;inset:0;border:1px dashed rgba(214,217,234,.45);border-radius:50%}
154: .ring.r2{inset:14%}.ring.r3{inset:28%}
155: .core{position:absolute;inset:38%;border-radius:50%;background:radial-gradient(circle at 35% 30%,#fff,#F2B63D 40%,#EF6F5E 80%);box-shadow:0 0 50px rgba(242,182,61,.55);display:grid;place-items:center;font:700 13px/1.1 var(--font-d);text-align:center;color:var(--ink);text-transform:uppercase}
156: .spin{position:absolute;inset:0;animation:spin 40s linear infinite}
157: .spin .pl{position:absolute;left:50%;top:0;width:0;height:0}
158: .pl{animation:spin 40s linear infinite reverse}
159: .pl i{position:absolute;left:-14px;top:-14px;width:28px;height:28px;border-radius:50%;border:2px solid var(--paper);display:block}
160: .pl b{position:absolute;left:-40px;width:80px;text-align:center;top:20px;font:600 12px/1 var(--font-m);letter-spacing:.08em;text-transform:uppercase;white-space:nowrap}
161: @keyframes spin{to{transform:rotate(360deg)}}
162: 
163: /* CORKBOARD */
164: .mat{background:var(--mat);color:var(--paper);padding-block:clamp(56px,7vw,100px)}
165: .mat .head{display:flex;flex-direction:column;gap:14px;margin-bottom:36px}
166: .mat .lead{color:#D2E2DF}
167: .board{position:relative;border:10px solid #7A4E2D;border-radius:6px;box-shadow:6px 6px 0 #0B2123,inset 0 0 0 2px rgba(0,0,0,.35);padding:44px clamp(14px,3vw,40px) 48px;background-color:#14383A;background-image:linear-gradient(rgba(255,255,255,.07) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.07) 1px,transparent 1px);background-size:24px 24px}
168: .cards{position:relative;z-index:2;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:56px clamp(16px,2.4vw,34px)}
169: .card{position:relative;color:var(--ink);cursor:default}
170: .card .card-in{background:var(--paper2);border:2px solid var(--ink);border-radius:var(--r);box-shadow:var(--shadow);padding:20px 16px 16px;display:flex;flex-direction:column;gap:8px;transform:rotate(var(--rot));transition:transform .15s cubic-bezier(.3,1.6,.5,1)}
171: .card:hover .card-in,.card:focus-visible .card-in{transform:rotate(0) translateY(-6px) scale(1.03)}
172: .card h3{font:700 26px/1 var(--font-d);text-transform:uppercase}
173: .card p{font-size:15px;line-height:1.35;color:var(--ink2)}
174: .card .num{font:600 11px/1 var(--font-m);letter-spacing:.12em;color:var(--ink2)}
175: .card .ico{width:48px;height:60px;align-self:flex-start;margin-bottom:2px}
176: .card .ico.sq{height:48px}
177: .tool{align-self:flex-start;font:600 11px/1 var(--font-m);letter-spacing:.08em;text-transform:uppercase;padding:5px 7px;border:2px solid var(--ink);border-radius:var(--r)}
178: .pin{position:absolute;z-index:3;left:50%;top:-8px;width:16px;height:16px;margin-left:-8px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#FF8A80,var(--red) 55%,#9C1B17);box-shadow:2px 3px 0 rgba(0,0,0,.4)}
179: #string{position:absolute;inset:0;z-index:1;pointer-events:none;overflow:visible}
180: .str{fill:none;stroke:var(--red);stroke-width:3;stroke-linecap:round;stroke-dasharray:1;stroke-dashoffset:1;transition:stroke-width .12s}
181: .str.lit{stroke:#FF6A5E;stroke-width:5;filter:drop-shadow(0 0 6px #FF6A5E)}
182: 
183: /* LOCKER */
184: .locker-sec{background:var(--paper3);padding-block:clamp(56px,7vw,100px)}
185: .locker-sec .head{display:flex;flex-direction:column;gap:14px;margin-bottom:34px}
186: .locker{display:flex;min-height:470px;border:2px solid var(--ink);border-radius:var(--r);overflow:hidden;box-shadow:8px 8px 0 var(--ink);background:#2B2A26}
187: .lt{position:relative;flex:0 0 68px;margin-left:-16px;background:var(--c);display:flex;flex-direction:row;min-width:0;border-radius:22px 0 0 0;box-shadow:-5px 0 0 rgba(15,18,38,.28);transition:flex-basis .35s cubic-bezier(.2,.9,.3,1)}
188: .lt:first-child{margin-left:0;border-radius:0}
189: .lt::after{content:"";position:absolute;inset:0;pointer-events:none;opacity:.5;mix-blend-mode:multiply;background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='g'><feTurbulence type='fractalNoise' baseFrequency='.8' numOctaves='3'/><feColorMatrix values='0 0 0 0 .3  0 0 0 0 .25  0 0 0 0 .2  0 0 0 .6 0'/></filter><rect width='100%' height='100%' filter='url(%23g)'/></svg>")}
190: .lt.pend{background:repeating-linear-gradient(135deg,var(--amber) 0 12px,#E5A62A 12px 24px)}
191: .lt.open{flex:1 1 0;min-width:0}
192: .lt-h{position:sticky;top:64px;z-index:2;flex:0 0 68px;align-self:flex-start;height:min(80vh,560px);margin:0;padding:0;background:transparent;border:0;cursor:pointer;display:flex;flex-direction:row;align-items:center;justify-content:center;gap:12px;color:var(--ink);transition:transform .2s ease-out}
193: .lt:not(.open) .lt-h:hover{transform:translateX(-4px)}
194: .lt-h .nm{order:1;writing-mode:vertical-rl;transform:rotate(180deg);font:700 22px/1 var(--font-d);text-transform:uppercase;letter-spacing:.04em;white-space:nowrap}
195: .lt-h .code{order:2;writing-mode:vertical-rl;transform:rotate(180deg);font:600 10px/1 var(--font-m);letter-spacing:.12em;white-space:nowrap}
196: .lt-h .code::after{content:attr(data-st)}
197: .lt-h .chip{position:absolute;width:1px;height:1px;padding:0;border:0;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
198: .panel{position:relative;z-index:2;display:none;flex:1;min-width:0;margin:0;background:var(--paper2);border-left:2px solid var(--ink);padding:30px 34px;gap:16px;flex-direction:column;align-content:flex-start}
